/bin/zsh -lc "node -e '
const Range = require(\"./classes/range\")
const Comparator = require(\"./classes/comparator\")
const satisfies = require(\"./functions/satisfies\")
const intersects = require(\"./ranges/intersects\")
console.log(\"runtime\", process.version)
function probe(label, f) {
  try { console.log(label, JSON.stringify(f())) } catch (e) { console.log(label, e.name + \": \" + e.message) }
}
for (const r of [\"1.2.3-alpha\", \"*\", \"* || 1.2.3-alpha\", \"1.2.3-alpha || *\"]) {
  probe(\"OR \" + r, () => { const a = new Range(r); return { parsed: a.range, pre: a.test(\"1.2.3-alpha\"), stable: a.test(\"1.2.3\") } })
}
for (const input of [\">=1.2.3-alpha\", \">=1.2.3\"]) {
  for (const v of [\"1.2.3\", \"1.2.3-beta\"]) {
    probe(\"comparator \" + input + \" / \" + v, () => new Range(new Comparator(input)).test(v))
    probe(\"string \" + input + \" / \" + v, () => new Range(input).test(v))
  }
}
probe(\"comparator includePrerelease\", () => new Range(new Comparator(\">=1.2.3\"), { includePrerelease: true }).test(\"1.2.4-beta\"))
probe(\"satisfies comparator\", () => satisfies(\"1.2.3-beta\", new Comparator(\">=1.2.3-alpha\")))
for (const [a,b,opts] of [
  [\">1.0.0 <1.0.1\", \"*\", undefined],
  [\">1.0.0 <1.0.1\", \"*\", {includePrerelease:true}],
  [\">=1.0.0-alpha <1.0.0\", \">=1.0.0-beta <1.0.0\", undefined],
  [\"1.0.0-alpha\", \">=1.0.0-alpha <1.0.0\", undefined],
]) probe(\"intersection \"+a+\" / \"+b+\" / \"+JSON.stringify(opts), () => intersects(a,b,opts))
'"

/bin/zsh -lc "node -e '
const Range = require(\"./classes/range\")
const intersects = require(\"./ranges/intersects\")
const o = {includePrerelease:true}
console.log(\"hyphen build lower-bound controls\")
for (const r of [\"1.2.3 - 2.0.0\", \"1.2.3+build - 2.0.0\", \"1.2.3 - 2.0.0+build\", \"1.2.3-alpha+build - 2.0.0\"]) {
 const a = new Range(r,o)
 console.log(JSON.stringify({input:r,parsed:a.range,pre:a.test(\"1.2.3-alpha\"),stable:a.test(\"1.2.3\")}))
}
console.log(\"intersection witnesses and controls\")
const a = new Range(\"1.0.0-alpha\")
const b = new Range(\">=1.0.0-alpha <1.0.0\")
console.log({a:a.range,b:b.range,aWitness:a.test(\"1.0.0-alpha\"),bWitness:b.test(\"1.0.0-alpha\"),ab:a.intersects(b),ba:b.intersects(a),explicit:intersects(a,b,{includePrerelease:true})})
const empty = new Range(\">1.0.0 <1.0.1\")
console.log({range:empty.range,intersectsStar:empty.intersects(new Range(\"*\")),self:empty.intersects(empty),tests:[\"1.0.0\",\"1.0.1-alpha\",\"1.0.1\",\"1.0.2\"].map(v=>[v,empty.test(v)]),withPrereleases:intersects(\">1.0.0 <1.0.1\",\"*\",o)})
let checks=0
const fails=[]
for (const [file,expect] of [[\"range-include\",true],[\"range-exclude\",false]]) {
 for (const [range,v,opts] of require(\"./test/fixtures/\"+file)) {
  checks++
  try { const actual=new Range(range,opts).test(v); if(actual"'!==expect) fails.push({range,v,opts,expect,actual}) } catch(e) {fails.push({range,v,error:String(e)})}
 }
}
for (const [a,b,expect] of require("./test/fixtures/range-intersection")) {checks++; if(intersects(a,b)!==expect) fails.push({a,b,expect})}
console.log("existing local fixture cases",JSON.stringify({checks,fails}))
'"'"
